namespace sv_b836f655ef7543fa98723328fc9576d6.Client.Models;

public sealed class StatusUpdate
{
    public required DateTime Timestamp { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
}

public sealed class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public required DateTime EstimatedDelivery { get; init; }
    public required List<StatusUpdate> Updates { get; init; }
}

using sv_b836f655ef7543fa98723328fc9576d6.Client.Models;

namespace sv_b836f655ef7543fa98723328fc9576d6.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_b836f655ef7543fa98723328fc9576d6.Client.Models;
using sv_b836f655ef7543fa98723328fc9576d6.Client.Services;

namespace sv_b836f655ef7543fa98723328fc9576d6.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTime(2026, 6, 22),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 17, 8, 0, 0), Status = "Picked Up", Location = "New York, NY" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 18, 14, 30, 0), Status = "In Transit", Location = "Philadelphia, PA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 19, 6, 15, 0), Status = "In Transit", Location = "Chicago, IL" },
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTime(2026, 6, 18),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 15, 9, 0, 0), Status = "Picked Up", Location = "Seattle, WA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 16, 11, 0, 0), Status = "In Transit", Location = "Portland, OR" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 17, 16, 45, 0), Status = "Out for Delivery", Location = "San Francisco, CA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 18, 10, 20, 0), Status = "Delivered", Location = "San Francisco, CA" },
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTime(2026, 6, 25),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 19, 7, 0, 0), Status = "Processing", Location = "Dallas, TX" },
            ]
        },
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;
using sv_b836f655ef7543fa98723328fc9576d6.Client.Models;

namespace sv_b836f655ef7543fa98723328fc9576d6.Client.Services;

public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_b836f655ef7543fa98723328fc9576d6.Client.Models
@using sv_b836f655ef7543fa98723328fc9576d6.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <p><strong>Loading shipment @TrackingNumber…</strong></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger mt-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <h3>Shipment @_shipment.TrackingNumber</h3>

    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>

        <dt>Current Location</dt>
        <dd>@_shipment.Location</dd>

        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("MMMM d, yyyy")</dd>
    </dl>

    <h4>Tracking History</h4>

    @if (_shipment.Updates.Count == 0)
    {
        <p>No updates available yet.</p>
    }
    else
    {
        <table class="table">
            <thead>
                <tr>
                    <th>Date &amp; Time</th>
                    <th>Status</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.Updates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Status</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request before starting a new one.
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Request was intentionally cancelled (navigation or dispose). Do nothing.
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = $"The request for shipment {TrackingNumber} timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = $"The request for shipment {TrackingNumber} timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = $"Something went wrong while loading shipment {TrackingNumber}. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

